    const addText=(text,x,y,size)=>{const line=document.createElementNS(ns,'text');line.setAttribute('x',x);line.setAttribute('y',y);line.setAttribute('font-family','Segoe UI, sans-serif');line.setAttribute('font-size',size);line.setAttribute('fill','#62766e');line.textContent=text;source.append(line)};
